extern "C"{DLLEXPORT void FillCHOPPluginInfo(CHOP_PluginInfo*i){if(!i->setAPIVersion(CHOPCPlusPlusAPIVersion))return;i->customOPInfo.opType->setString("Speechactivity");i->customOPInfo.opLabel->setString("Speech Activity");i->customOPInfo.opIcon->setString("SAC");i->customOPInfo.authorName->setString("TDAppleML");i->customOPInfo.minInputs=1;i->customOPInfo.maxInputs=1;}DLLEXPORT CHOP_CPlusPlusBase*CreateCHOPInstance(const OP_NodeInfo*i){return new VoiceActivityCHOP(i);}DLLEXPORT void DestroyCHOPInstance(CHOP_CPlusPlusBase*i){delete static_cast<VoiceActivityCHOP*>(i);}}
